import{_ as t,o as a,c as r,a as d}from"./app.Dzj71sBz.js";const u=JSON.parse('{"title":"Rust-Based CLI Tooling","description":"","frontmatter":{},"headers":[],"relativePath":"reference/RUST_TOOLING.md","filePath":"reference/RUST_TOOLING.md","lastUpdated":1771753292000}'),s={name:"reference/RUST_TOOLING.md"};function i(o,e,n,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="rust-based-cli-tooling" tabindex="-1">Rust-Based CLI Tooling <a class="header-anchor" href="#rust-based-cli-tooling" aria-label="Permalink to &quot;Rust-Based CLI Tooling&quot;">​</a></h1><p>thegent uses Rust alternatives for common CLI tools to accelerate hooks and agent execution. This document maps tools, describes integration, and documents known issues.</p><h2 id="tool-mapping" tabindex="-1">Tool Mapping <a class="header-anchor" href="#tool-mapping" aria-label="Permalink to &quot;Tool Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Legacy</th><th>Rust Alternative</th><th>Drop-in</th><th>Speedup</th><th>Integration</th></tr></thead><tbody><tr><td>grep</td><td>ripgrep (rg)</td><td>Partial</td><td>2-10x (recursive)</td><td>grep-wrapper.sh routes grep→rg</td></tr><tr><td>find</td><td>fd</td><td>Partial</td><td>3-23x</td><td>fd-wrapper.sh, find() override</td></tr><tr><td>jq</td><td>jaq</td><td>Yes</td><td>2-10x</td><td>JQ_CMD (jaq first)</td></tr><tr><td>uniq</td><td>huniq</td><td>Partial</td><td>2-3x</td><td>HUNIQ_CMD in sort_unique</td></tr><tr><td>ps/pgrep</td><td>procs</td><td>Partial</td><td>2-3x</td><td>procs-wrapper.sh</td></tr><tr><td>shasum/sha256sum (cache keys)</td><td>b3sum</td><td>Partial</td><td>2-5x</td><td>HASH_CMD, hash_for_cache (WP-B)</td></tr></tbody></table><h2 id="integration-points" tabindex="-1">Integration Points <a class="header-anchor" href="#integration-points" aria-label="Permalink to &quot;Integration Points&quot;">​</a></h2><ul><li>undefined<strong>hooks/lib/common.sh</strong>: Sources fd-wrapper, grep-wrapper, procs-wrapper; caches JQ_CMD, RG_CMD, HUNIQ_CMD, HASH_CMD</li><li>undefined<strong>hooks/hook-dispatcher</strong>: Exports RG_CMD, JQ_CMD, TIMEOUT_CMD to child hooks</li><li>undefined<strong>grep-wrapper.sh</strong>: Overrides <code>grep</code>; routes -r, -nE, -oE, -cE, -q, -l, -L to rg; fallback to system grep for -P, --include</li></ul><h2 id="ripgrep-and-claude-code" tabindex="-1">Ripgrep and Claude Code <a class="header-anchor" href="#ripgrep-and-claude-code" aria-label="Permalink to &quot;Ripgrep and Claude Code&quot;">​</a></h2><h3 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known Issues&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Issue</th><th>Severity</th><th>Workaround</th></tr></thead><tbody><tr><td><a href="https://github.com/BurntSushi/ripgrep/issues/3259" target="_blank" rel="noreferrer">ripgrep#3259</a></td><td>Edge case</td><td>rg fails on paths &gt;32k deep; use grep fallback</td></tr><tr><td><a href="https://github.com/anthropics/claude-code/issues/22176" target="_blank" rel="noreferrer">claude-code#22176</a></td><td>Regression</td><td>Built-in rg EAGAIN timeout on large gitignored dirs</td></tr><tr><td><a href="https://github.com/anthropics/claude-code/issues/22341" target="_blank" rel="noreferrer">claude-code#22341</a></td><td>Critical</td><td>VSCode OOM after rg EAGAIN spawn failures</td></tr></tbody></table><h3 id="recommended-use-system-ripgrep" tabindex="-1">Recommended: Use System Ripgrep <a class="header-anchor" href="#recommended-use-system-ripgrep" aria-label="Permalink to &quot;Recommended: Use System Ripgrep&quot;">​</a></h3><p>Add to <code>~/.zshrc</code> or <code>~/.bashrc</code>:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> USE_BUILTIN_RIPGREP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Use system rg (5-10x faster than bundled)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then ensure ripgrep is installed: <code>brew install ripgrep</code> (already in Brewfile).</p><h2 id="grep-vs-rg-semantics" tabindex="-1">Grep vs rg Semantics <a class="header-anchor" href="#grep-vs-rg-semantics" aria-label="Permalink to &quot;Grep vs rg Semantics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>grep</th><th>rg equivalent</th></tr></thead><tbody><tr><td><code>grep -nE &#39;pat&#39; file</code></td><td><code>rg -n &#39;pat&#39; file</code></td></tr><tr><td><code>grep -r pattern dir</code></td><td><code>rg pattern dir</code></td></tr><tr><td><code>grep -oE &#39;pat&#39;</code></td><td><code>rg -o &#39;pat&#39;</code></td></tr><tr><td><code>grep -cE &#39;pat&#39;</code></td><td><code>rg -c &#39;pat&#39;</code></td></tr><tr><td><code>grep -q &#39;pat&#39;</code></td><td><code>rg -q &#39;pat&#39;</code></td></tr><tr><td><code>grep -L &#39;pat&#39; files</code></td><td><code>rg -L &#39;pat&#39; files</code></td></tr><tr><td><code>grep -v -E &#39;pat&#39;</code></td><td><code>rg -v &#39;pat&#39;</code></td></tr><tr><td><code>grep --exclude-dir=X</code></td><td><code>rg -g &#39;!X&#39;</code></td></tr></tbody></table><h2 id="brewfile" tabindex="-1">Brewfile <a class="header-anchor" href="#brewfile" aria-label="Permalink to &quot;Brewfile&quot;">​</a></h2><p>Run <code>brew bundle</code> from the project root to install ripgrep, fd, jaq, procs (and other deps). Optional: huniq (cargo install huniq), eza (brew install eza), b3sum (brew install b3sum for faster cache key hashing).</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p>undefined<strong>Extended on:</strong> 2026-02-17 undefined<strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',29)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
